import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';

@Component({
  selector: 'app-renewal-details',
  templateUrl: './renewal-details.page.html',
  styleUrls: ['./renewal-details.page.scss'],
})
export class RenewalDetailsPage implements OnInit {

  onstartclass = [
    {label: "LKG",value: 1 },
    {label: "I",value: 2 },
    {label: "II",value: 3 },
    {label: "III",value: 4 },
  ]

  onendclass  = [
    {label: "UKG",value: 1 },
    {label: "I",value: 2 },
    {label: "II",value: 3 },
    {label: "III",value: 4 },
    {label: "IV",value: 5 },
    {label: "V",value: 6 },
    {label: "VI",value: 7 },
    {label: "VII",value: 8 },
    {label: "VIII",value: 9 },
    {label: "IX",value: 10 },
    {label: "X",value: 11 },
    {label: "XI",value: 12 },
    {label: "XII",value: 13 }
  ]

  routeData: any;
  status: any;
  uidse: any;
    constructor(private route: ActivatedRoute,
    private router: Router) { }

  owner: [{value:"1",label:"text"}]

  ngOnInit() {
  }
 
  ionViewDidEnter() {
    this.routeData = this.route.snapshot;
    this.status = this.routeData.queryParams.status;
    this.uidse = this.routeData.queryParams.uidse;
  }

  onGoButton() {
    this.router.navigate(['/tabs/regulator-section'], {
      queryParams: { status: 1, "uidse": this.uidse }, skipLocationChange: false
    });  
  }
  
  onSave() {
    this.router.navigate(['/tabs/regulator-section'], {
      queryParams: { status: 2, "uidse": this.uidse }, skipLocationChange: false
    });
  }

}
